CREATE TABLE dbo.MaintenanceLogs (
  MaintenanceLogId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_MaintenanceLogs_Id DEFAULT NEWSEQUENTIALID(), AssetId UNIQUEIDENTIFIER NOT NULL,
  MaintenanceType VARCHAR(30) NOT NULL, PerformedAt DATETIME2 NOT NULL, Result VARCHAR(20) NOT NULL, NextDueAt DATETIME2 NULL,
  Details NVARCHAR(1000) NULL, PerformedBy NVARCHAR(200) NOT NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_MaintenanceLogs_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_MaintenanceLogs PRIMARY KEY(MaintenanceLogId), CONSTRAINT FK_MaintenanceLogs_Asset FOREIGN KEY(AssetId) REFERENCES dbo.Assets(AssetId),
  CONSTRAINT CK_MaintenanceLogs_Result CHECK(Result IN ('PASS','FAIL','LIMITED'))
);
CREATE TABLE dbo.ReconciliationItems (
  ReconciliationItemId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ReconciliationItems_Id DEFAULT NEWSEQUENTIALID(), ReconciliationDate DATE NOT NULL,
  BranchId UNIQUEIDENTIFIER NOT NULL, ItemType VARCHAR(50) NOT NULL, ReferenceType VARCHAR(80) NULL, ReferenceId UNIQUEIDENTIFIER NULL,
  Severity VARCHAR(20) NOT NULL, Description NVARCHAR(1000) NOT NULL, OwnerId UNIQUEIDENTIFIER NOT NULL, DueAt DATETIME2 NULL,
  Status VARCHAR(20) NOT NULL CONSTRAINT DF_ReconciliationItems_Status DEFAULT 'OPEN', Resolution NVARCHAR(1000) NULL,
  CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ReconciliationItems_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL, Version ROWVERSION NOT NULL,
  CONSTRAINT PK_ReconciliationItems PRIMARY KEY(ReconciliationItemId), CONSTRAINT FK_ReconciliationItems_Branch FOREIGN KEY(BranchId) REFERENCES dbo.Branches(BranchId),
  CONSTRAINT FK_ReconciliationItems_Owner FOREIGN KEY(OwnerId) REFERENCES dbo.Users(UserId), CONSTRAINT CK_ReconciliationItems_Severity CHECK(Severity IN ('LOW','MEDIUM','HIGH','CRITICAL')),
  CONSTRAINT CK_ReconciliationItems_Status CHECK(Status IN ('OPEN','IN_PROGRESS','PENDING_APPROVAL','RESOLVED','CLOSED'))
);
CREATE TABLE dbo.ReportDefinitions (
  ReportDefinitionId UNIQUEIDENTIFIER NOT NULL CONSTRAINT DF_ReportDefinitions_Id DEFAULT NEWSEQUENTIALID(), Code VARCHAR(50) NOT NULL,
  Name NVARCHAR(200) NOT NULL, DefinitionJson NVARCHAR(MAX) NOT NULL, VersionNo INT NOT NULL, Status VARCHAR(20) NOT NULL CONSTRAINT DF_ReportDefinitions_Status DEFAULT 'DRAFT',
  ApprovedBy UNIQUEIDENTIFIER NULL, CreatedAt DATETIME2 NOT NULL CONSTRAINT DF_ReportDefinitions_CreatedAt DEFAULT SYSUTCDATETIME(), CreatedBy VARCHAR(100) NOT NULL,
  CONSTRAINT PK_ReportDefinitions PRIMARY KEY(ReportDefinitionId), CONSTRAINT UQ_ReportDefinitions_Code_Version UNIQUE(Code, VersionNo),
  CONSTRAINT FK_ReportDefinitions_Approver FOREIGN KEY(ApprovedBy) REFERENCES dbo.Users(UserId), CONSTRAINT CK_ReportDefinitions_Json CHECK(ISJSON(DefinitionJson)=1),
  CONSTRAINT CK_ReportDefinitions_Status CHECK(Status IN ('DRAFT','APPROVED','RETIRED'))
);
